 if(state.suspended)return;const cleric=party.members.find(m=>m.classId==='cleric'),auraLevel=party.levels.cleric_regen||0;rig.aura.visible=!!(cleric&&auraLevel);if(rig.aura.visible){const radius=220+(auraLevel-1)*20;place(rig.aura,cleric.x,cleric.y,radius*2*(1+.012*Math.sin(party.time*2)),party.time*.045,.15+state.regenPulse*.30)}
 for(let i=0;i<3;i++){const mark=state.healMarks[i],sprite=rig.particles[i],ally=mark.life>0?party.members.find(m=>m.classId===mark.classId):null;sprite.visible=!!ally;if(ally)place(sprite,ally.x+Math.sin(party.time*3+i)*15,ally.y-55-(1-mark.life/.65)*28,42,0,Math.min(1,mark.life/.25)*.8)}
 const h=state.hammers;for(let i=0;i<3;i++){const d=h.drops[i],marker=rig.markers[i],sprite=rig.hammers[i],impact=rig.impacts[i];marker.visible=sprite.visible=impact.visible=false;if(!h.active||i>=h.count||!d.valid)continue;if(!d.done&&h.age>=d.delay-.5)place(marker,d.x,d.y,180,0,.6);const p=(h.age-(d.delay-.25))/.25;if(!d.done&&p>=0&&p<=1)place(sprite,d.x,d.y-(1-p)*100,90+p*12,Math.sin(p*Math.PI)*.08,.9);if(d.life>0)place(impact,d.x,d.y,180*(1-d.life/.4*.4),0,Math.min(1,d.life/.4*1.4))}
